/* jQuery UI prototype. All state is fictional and stays in this browser. */
$(function(){
  'use strict';
  let auth;try{auth=JSON.parse(sessionStorage.getItem('ai14-demo-session'));}catch{}
  if(!auth?.verified||!['admin','teacher'].includes(auth.role)){location.replace('login.html');return;}
  $('#signed-in-role').text(auth.role==='admin'?'Admin':'Teacher');
  const KEY='ai14-educontrol-ui-v03';let cached=null;try{cached=JSON.parse(localStorage.getItem(KEY));}catch{}
  let store=new EduDemo.Store(cached?.schema===1?cached:null),role=auth.role,teacherId=auth.teacherId||'T001',page='overview',draft=null,selectedRun=null,reviewTab='Pending',sessionFilter='',query='',modalFocus=null;
  const paths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',sessions:'M8 3h8v4H8z M6 5H4v16h16V5h-2 M8 12h8 M8 16h6',reviews:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',teachers:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M20 8v6 M17 11h6 M19 21v-2a4 4 0 0 0-3-4',classes:'M4 4h6l2 2 2-2h6v16h-6l-2 2-2-2H4z M12 6v16',payroll:'M5 3h14v18H5z M8 6h8v4H8z M8 14h1 M12 14h1 M16 14h1 M8 18h1 M12 18h1 M16 18h1',payments:'M3 6h18v14H3z M3 10h18 M7 16h4',audit:'M4 12a8 8 0 1 0 3-6 M4 3v5h5 M12 7v5l3 2',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l4 2',arrow:'M5 12h14 M14 7l5 5-5 5',plus:'M12 5v14 M5 12h14',check:'M5 12l4 4L19 6',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16',search:'M11 3a8 8 0 1 0 0 16 8 8 0 0 0 0-16 M17 17l4 4',alert:'M12 3L2 21h20z M12 9v5 M12 17h.01',leaf:'M20 3C9 2 3 8 5 15s12 8 15-12z M5 20l9-10'};
  const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.sessions}"/></svg>`;
  const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const mmk=n=>Number(n).toLocaleString('en-US');
  const teacher=id=>store.teacher(id),cls=id=>store.data.classes.find(c=>c.id===id);
  const time=s=>s?new Date(s).toLocaleTimeString('en-GB',{timeZone:'Asia/Yangon',hour:'2-digit',minute:'2-digit'}):'—';
  const day=s=>s?new Date(s).toLocaleDateString('en-GB',{timeZone:'Asia/Yangon',day:'2-digit',month:'short'}):'—';
  const localDate=s=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Yangon',year:'numeric',month:'2-digit',day:'2-digit'}).format(s?new Date(s):new Date());
  const localInput=s=>s?`${localDate(s)}T${time(s)}`:'';
  const iso=s=>s?s+':00+06:30':null;
  const init=t=>t.name.split(' ').map(n=>n[0]).slice(0,2).join('');
  const avatar=t=>`<span class="avatar tone-${t.tone%5}">${init(t)}</span>`;
  const person=id=>{const t=teacher(id);return `<div class="person">${avatar(t)}<div><strong>${e(t.name)}</strong><small>${e(t.id)}</small></div></div>`;};
  function badge(status){const type=({'Verified':'verified','Approved':'approved','Paid':'paid','Pending':'pending','Draft':'draft','Rejected':'rejected','Missing checkout':'missing','In progress':'progress','Void':'void','Reversed':'void','Active':'verified','Inactive':'void','Withdrawn':'void','Not paid':'pending'})[status]||'pending';return `<span class="badge ${type}">${e(status)}</span>`;}
  const button=(label,action,id='',type='')=>`<button type="button" class="btn ${type}" data-action="${action}" data-id="${e(id)}">${label}</button>`;
  const empty=(title,text='You’re all caught up.')=>`<div class="empty">${icon('leaf')}<h3>${title}</h3><p>${text}</p></div>`;
  const th=labels=>`<thead><tr>${labels.map(x=>`<th>${x}</th>`).join('')}</tr></thead>`;
  const field=(label,name,type='text',value='',required=true)=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${e(value)}" ${required?'required':''}></label>`;
  const selectField=(label,name,options)=>`<label class="field"><span>${label}</span><select name="${name}">${options}</select></label>`;
  const opts=(list,selected,key='id',label='name')=>list.map(x=>`<option value="${e(x[key])}" ${x[key]===selected?'selected':''}>${e(x[label])}</option>`).join('');
  const textarea=(label,name)=>`<label class="field"><span>${label}</span><textarea name="${name}" required placeholder="အကြောင်းပြချက် ရေးပါ…"></textarea></label>`;
  const formEnd=(text='Save changes')=>`<div class="form-actions">${button('Cancel','close-modal')}<button class="btn primary" type="submit">${text}</button></div>`;
  function persist(){try{localStorage.setItem(KEY,JSON.stringify(store.data));}catch{toast('Browser storage is unavailable. Changes last for this tab only.');}}
  function toast(message){$('#toast').text(message).addClass('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').removeClass('show'),3500);}
  function openModal(title,body,eyebrow='PARAMI ACADEMY'){modalFocus=document.activeElement;$('#modal-title').text(title);$('#modal-eyebrow').text(eyebrow);window.destroyControls('#modal-body');$('#modal-body').html(body);window.enhanceControls('#modal-body');$('#modal-error').addClass('hidden');$('#modal').removeClass('hidden');$('body').css('overflow','hidden');setTimeout(()=>$('#modal').find('input,select,textarea,button,[tabindex]:not([tabindex="-1"])').filter(':visible').first().trigger('focus'),20);}
  function closeModal(){$('select').each(function(){if($(this).selectmenu('instance'))$(this).selectmenu('close');});$('#modal').addClass('hidden');$('body').css('overflow','');modalFocus?.focus();}
  function fail(err){if(!$('#modal').hasClass('hidden'))$('#modal-error').text(err.message).removeClass('hidden');else toast(err.message);}
  function commit(fn,message){try{fn();persist();closeModal();render();if(message)toast(message);}catch(err){fail(err);}}
  function head(eyebrow,title,subtitle,actions=''){return `<section class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtext">${subtitle}</p></div><div class="flex items-center gap-2">${actions}</div></section>`;}
  function stat(label,value,unit,note,glyph='clock',warm=false){return `<article class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon ${warm?'warm':''}">${icon(glyph)}</span></div><div class="stat-value">${value}<small>${unit}</small></div><div class="stat-foot"><span class="pill-dot"></span>${note}</div></article>`;}
  function nav(){const admin=[['overview','Overview'],['teachers','Teachers'],['classes','Classes & assignments'],['sessions','Class records'],['reviews','Verification'],['payroll','Payroll'],['payments','Payment history'],['audit','Activity log']],teach=[['home','My workspace'],['sessions','My class records'],['reviews','My corrections'],['payments','My payments']];$('#nav').html((role==='admin'?admin:teach).map(([id,label])=>`<a class="nav-link ${page===id?'active':''}" href="#${id}">${icon(id==='home'?'overview':id)}${label}${id==='reviews'&&store.data.corrections.filter(c=>c.status==='Pending'&&(role==='admin'||store.session(c.session).teacher===teacherId)).length?`<span class="count">${store.data.corrections.filter(c=>c.status==='Pending'&&(role==='admin'||store.session(c.session).teacher===teacherId)).length}</span>`:''}</a>`).join(''));$('#profile-name').text(role==='admin'?'Admin workspace':teacher(teacherId).name);$('#profile-role').text(role==='admin'?'School administrator':'Teacher · '+teacherId);$('#breadcrumb-title').text((role==='admin'?admin:teach).find(x=>x[0]===page)?.[1]||'Workspace');}
  function sessionsTable(list,compact=false){return `<div class="table-scroll"><table>${th(['Teacher','Class / subject','Date','Teaching time','Hours','Status',...(compact?[]:[''])])}<tbody>${list.map(s=>`<tr><td>${person(s.teacher)}</td><td><strong>${e(cls(s.classId)?.subject||s.classId)}</strong><div class="subtext" style="margin:3px 0 0;font-size:9px">${e(s.id.slice(0,12))}</div></td><td>${day(s.start)}</td><td>${time(s.start)} <span style="color:#bcc4b5">→</span> ${time(s.end)}</td><td>${s.end?(EduDemo.mins(s.start,s.end)/60).toFixed(2):'—'}</td><td>${badge(!s.end?'Missing checkout':s.status)}</td>${compact?'':`<td>${button('View '+icon('arrow'),'session-detail',s.id,'small')}</td>`}</tr>`).join('')}</tbody></table></div>${!list.length?empty('No class records','Try another filter or add a new session.'):''}`;}
  function overview(){const d=store.data,verified=d.sessions.filter(s=>!store.reason(s)),minutes=verified.reduce((n,s)=>n+EduDemo.mins(s.start,s.end),0),pay=verified.reduce((n,s)=>n+EduDemo.money(EduDemo.mins(s.start,s.end),store.rate(s)),0),pending=d.sessions.filter(s=>s.status==='Pending').length,corrections=d.corrections.filter(c=>c.status==='Pending').length;
    let html=head('YOUR ACADEMY AT A GLANCE','A little clarity. A better school.','သင်ကြားမှုမှတ်တမ်း၊ စစ်ဆေးမှုနဲ့ ဆရာကြေး — တစ်နေရာတည်းမှာ။',`<span class="date-control">${icon('calendar')} 12 – 18 Oct 2026</span>${button(icon('plus')+' Add class record','add-session','','primary')}`);
    html+=`<section class="hero"><div><div class="eyebrow">LESS ADMIN MORE TEACHING</div><h2>Your teaching records, thoughtfully organised.</h2><p>အတည်ပြုပြီးတဲ့ အချိန်ကိုပဲ ဆရာကြေးတွက်ပါ။<br>Review this week’s records and keep every payment on track.</p></div><div class="hero-art" aria-hidden="true"><div class="paper"></div><div class="hero-check">${icon('check')}</div></div></section><section class="stats-grid">${stat('Active teachers',d.teachers.filter(t=>t.active).length,'teachers','Across 3 subjects','teachers')}${stat('Payroll-ready hours', (minutes/60).toFixed(2),'hours','Verified & not yet allocated','clock')}${stat('Needs your review',pending,'records',corrections+' pending corrections','reviews',true)}${stat('Eligible payroll',mmk(pay),'MMK','Verified sessions only','payments')}</section>`;
    const days=[12,13,14,15,16,17,18],daily=days.map(day=>d.sessions.filter(s=>s.start.slice(8,10)===String(day)&&s.end).reduce((n,s)=>n+EduDemo.mins(s.start,s.end)/60,0));
    html+=`<section class="two-col"><div class="card"><div class="card-head"><div><h2>Teaching activity</h2><p class="subtext">A quieter way to see your week</p></div><span class="mini-badge">This week</span></div><div class="chart-area"><div class="chart-legend"><strong>${daily.reduce((n,x)=>n+x,0).toFixed(2)} <span style="font-size:10px;font-weight:400">total hours</span></strong><span><i></i> Recorded hours</span></div><div class="bar-chart">${days.map((day,i)=>`<div class="bar-group"><div class="bar light" style="height:88%"></div><div class="bar" style="height:${Math.max(2,daily[i]/6*100)}%" title="${day} Oct: ${daily[i].toFixed(2)} hours"></div><span class="bar-label">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]}</span></div>`).join('')}</div><div class="chart-bottom">${icon('clock')} Original and effective class times · 12–18 October</div></div></div><div class="card"><div class="card-head"><div><h2>A little attention needed</h2><p class="subtext">Keep your records in good shape</p></div>${icon('reviews')}</div><div class="review-row"><span class="review-symbol">${icon('sessions')}</span><div><strong>Class records to verify</strong><p>စစ်ဆေးရန် ကျန်ရှိသောမှတ်တမ်းများ</p><a href="#sessions" class="text-link">Review records ${icon('arrow')}</a></div><span class="number">${pending}</span></div><div class="review-row"><span class="review-symbol">${icon('clock')}</span><div><strong>Time correction requests</strong><p>ဆရာများရဲ့ အချိန်ပြင်ဆင်ရန် တောင်းဆိုမှု</p><a href="#reviews" class="text-link">Review requests ${icon('arrow')}</a></div><span class="number">${corrections}</span></div><div class="review-row"><span class="review-symbol">${icon('alert')}</span><div><strong>Missing checkout</strong><p>Checkout မပါသေးတဲ့ အတန်းမှတ်တမ်း</p><a href="#sessions" class="text-link">View class records ${icon('arrow')}</a></div><span class="number">${d.sessions.filter(s=>!s.end).length}</span></div></div></section>`;
    html+=`<section class="card"><div class="card-head"><div><h2>Recent class records</h2><p class="subtext">Every class has a clear record.</p></div><a class="text-link" href="#sessions">View all records ${icon('arrow')}</a></div>${sessionsTable([...d.sessions].sort((a,b)=>new Date(b.start)-new Date(a.start)).slice(0,5),true)}<div class="table-foot"><span>${d.sessions.length} records in your workspace</span><span>Sample data · October 2026</span></div></section>`;return html;
  }
  function home(){const t=teacher(teacherId),mine=store.data.sessions.filter(s=>s.teacher===t.id),open=mine.find(s=>!s.end);return head('TEACHER WORKSPACE',`မင်္ဂလာပါ ${e(t.name.split(' ')[0])}။`,'A good day starts with a clear record.',`<span class="mini-badge">${e(t.name)} · ${t.id}</span>`)+`<section class="two-col"><div class="clock-card"><div class="eyebrow">${open?'YOUR CLASS IS IN PROGRESS':'READY FOR YOUR NEXT CLASS'}</div><div class="live-clock" id="live-clock">${time(new Date())}</div><p>Yangon time · ${new Date().toLocaleDateString('en-GB',{timeZone:'Asia/Yangon',day:'numeric',month:'long',year:'numeric'})}</p>${open?`<hr class="divider"><h3>${e(cls(open.classId).name)}</h3><p>Checked in ${day(open.start)} at ${time(open.start)}<br>အတန်းပြီးရင် Check out နှိပ်ပါ။</p>${button(icon('check')+' Check out','checkout',open.id,'primary')}<div style="margin-top:12px">${button('Forgot to check out? Request correction','request',open.id,'small')}</div>`:`<p>သင်မည့်အတန်းကို ရွေးပြီး Check in လုပ်ပါ။<br>Recorded times use your browser clock in this UI demo.</p>`}</div><div class="card"><div class="card-head"><div><h2>Your assigned classes</h2><p class="subtext">Only your active classes appear here</p></div>${icon('classes')}</div>${t.assignments.filter(id=>cls(id)?.active).map(id=>`<div class="class-option"><span class="class-glyph">${icon('classes')}</span><div><h3>${e(cls(id).subject)}</h3><p>${id} · ${t.active?'Active assignment':'Account inactive'}</p></div><button class="btn ${open?'':'primary'}" data-action="checkin" data-id="${id}" ${open||!t.active?'disabled':''}>${icon('plus')} Check in</button></div>`).join('')}</div></section><section class="stats-grid">${stat('My class records',mine.length,'classes','Your teaching history','sessions')}${stat('Verified hours',(mine.filter(s=>s.status==='Verified').reduce((n,s)=>n+EduDemo.mins(s.start,s.end),0)/60).toFixed(2),'hours','Admin-reviewed records','clock')}${stat('Pending corrections',store.data.corrections.filter(c=>c.status==='Pending'&&store.session(c.session).teacher===t.id).length,'requests','View My corrections','reviews',true)}${stat('Approved payment',mmk(store.data.runs.filter(r=>r.status==='Approved').reduce((n,r)=>n+store.total(r,t.id).net,0)),'MMK','Approved payroll only','payments')}</section><section class="card"><div class="card-head"><h2>Your recent classes</h2><a href="#sessions" class="text-link">All my records ${icon('arrow')}</a></div>${sessionsTable([...mine].reverse().slice(0,5))}</section>`;}
  function sessions(){return head(role==='admin'?'CLASS MANAGEMENT':'MY TEACHING HISTORY',role==='admin'?'Class records':'My class records','သင်ကြားမှုတစ်ခုချင်းစီရဲ့ အချိန်နဲ့ အတည်ပြုမှုအခြေအနေကို ကြည့်ပါ။',role==='admin'?button(icon('plus')+' Add class record','add-session','','primary'):'')+`<section class="card"><div class="toolbar"><input type="search" id="session-search" placeholder="Search teacher, subject or record…" value="${e(query)}" aria-label="Search records"><select id="session-filter" aria-label="Filter session status"><option value="">All statuses</option>${['Pending','Verified','Rejected','Missing checkout'].map(x=>`<option ${sessionFilter===x?'selected':''}>${x}</option>`).join('')}</select><span class="spacer"></span><span class="mini-badge">${role==='teacher'?teacher(teacherId).name:'All teachers'}</span></div><div id="session-results"></div></section>`;}
  function filterSessions(){const list=store.data.sessions.filter(s=>role==='admin'||s.teacher===teacherId).filter(s=>!sessionFilter||(sessionFilter==='Missing checkout'?!s.end:s.status===sessionFilter)).filter(s=>!query||[s.id,teacher(s.teacher).name,cls(s.classId).subject].join(' ').toLowerCase().includes(query.toLowerCase())).sort((a,b)=>new Date(b.start)-new Date(a.start));$('#session-results').html(sessionsTable(list)+`<div class="table-foot"><span>${list.length} class records</span><span>Times shown in Asia/Yangon</span></div>`);}
  function reviews(){const requests=store.data.corrections.filter(c=>(role==='admin'||store.session(c.session).teacher===teacherId)&&(reviewTab==='All'||c.status===reviewTab));return head('REVIEW & CORRECTIONS',role==='admin'?'A closer look, a clearer record.':'My correction requests',role==='admin'?'အချိန်ပြင်ဆင်မှုကို စစ်ပြီး session ကို သီးခြား Verify လုပ်ပါ။':'မိမိတောင်းဆိုမှုအခြေအနေနဲ့ Admin ရဲ့မှတ်ချက်ကို ကြည့်ပါ။')+`<div class="notice ${role==='teacher'?'green':''}">${icon('reviews')}<span>${role==='admin'?'Approving a correction updates effective times. The session still needs verification before payroll.':'Original times stay in your history. Pending corrections hold the session from payroll.'}</span></div><section class="card" style="margin-bottom:20px"><div class="tabs">${['Pending','Approved','Rejected','All'].map(x=>`<button class="tab ${reviewTab===x?'active':''}" data-action="review-tab" data-id="${x}">${x}</button>`).join('')}</div></section><section class="review-grid">${requests.map(c=>{const s=store.session(c.session);return `<article class="card request-card"><div class="request-top">${person(s.teacher)}${badge(c.status)}</div><div class="eyebrow">${e(cls(s.classId).subject)} · ${day(s.start)} · ${s.id}</div><div class="time-compare"><div class="time-box"><label>ORIGINAL RECORD</label><strong>${time(s.originalStart)} – ${time(s.originalEnd)}</strong></div>${icon('arrow')}<div class="time-box new"><label>REQUESTED TIME</label><strong>${time(c.start)} – ${time(c.end)}</strong></div></div><p class="request-reason">“${e(c.reason)}”</p>${c.comment?`<p class="request-reason"><strong>Admin:</strong> ${e(c.comment)}</p>`:''}<div class="flex gap-2">${c.status==='Pending'?(role==='admin'?button(icon('check')+' Review request','review',c.id,'primary small')+button('View session','session-detail',s.id,'small'):button('Withdraw request','withdraw',c.id,'small')):button('View session','session-detail',s.id,'small')}</div></article>`;}).join('')}</section>${requests.length?'':`<div class="card">${empty('No '+reviewTab.toLowerCase()+' corrections','Your class records are in good hands.')}</div>`}`;}
  function teachers(){return head('PEOPLE & PROFILES','The people behind every class.','ဆရာအချက်အလက်၊ အတန်းသတ်မှတ်မှုနဲ့ hourly rate များကို စီမံပါ။',button(icon('plus')+' Add teacher','add-teacher','','primary'))+`<section class="teacher-grid">${store.data.teachers.map(t=>`<article class="card teacher-card"><header>${avatar(t)}${badge(t.active?'Active':'Inactive')}</header><h3>${e(t.name)}</h3><p>${e(t.email)}<br>${t.id} · ${t.assignments.map(id=>e(cls(id).subject)).join(' / ')}</p><div class="rate"><span>Current hourly rate</span><strong>${mmk([...t.rates].sort((a,b)=>b.from.localeCompare(a.from))[0]?.rate||0)} <small style="font-size:9px;font-weight:400">MMK/hr</small></strong></div><div class="card-actions">${button('Profile & rates','teacher-profile',t.id,'small')}${button(t.active?'Deactivate':'Activate','toggle-teacher',t.id,'small')}</div></article>`).join('')}</section>`;}
  function classes(){return head('CLASSES & ASSIGNMENTS','A place for every subject.','ဆရာနဲ့ အတန်းချိတ်ဆက်မှုကို စီမံပါ။',button(icon('plus')+' Add class','add-class','','primary'))+`<section class="teacher-grid">${store.data.classes.map(c=>`<article class="card teacher-card"><header><span class="class-glyph">${icon('classes')}</span>${badge(c.active?'Active':'Inactive')}</header><h3>${e(c.name)}</h3><p>${c.id} · ${e(c.subject)}</p><hr class="divider"><div class="eyebrow">ASSIGNED TEACHERS</div>${store.data.teachers.filter(t=>t.assignments.includes(c.id)).map(t=>`<div class="person" style="margin:11px 0">${avatar(t)}<strong style="font-size:11px">${e(t.name)}</strong></div>`).join('')||'<p>No teachers assigned yet.</p>'}<div class="card-actions">${button('Edit assignments','assignments',c.id,'small')}${button(c.active?'Deactivate':'Activate','toggle-class',c.id,'small')}</div></article>`).join('')}</section>`;}
  function payroll(){const run=selectedRun?store.data.runs.find(r=>r.id===selectedRun):draft;return head('HOURS INTO PAYMENTS','Fair hours. Clear payments.','အတည်ပြုထားတဲ့ သင်ကြားချိန်များအတွက် ဆရာကြေးတွက်ပါ။',`<span class="mini-badge">Admin approval</span>`)+`<div class="notice green">${icon('reviews')}<span>Only verified sessions with complete times and no pending correction are included. အတည်ပြုပြီးစာရင်းကို snapshot အဖြစ်သိမ်းထားပါတယ်။</span></div><section class="card" style="margin-bottom:22px"><div class="toolbar"><label style="font-size:10px;color:#8e9c7d">Period start <input type="date" id="period-from" value="${run?.from||'2026-10-12'}"></label><label style="font-size:10px;color:#8e9c7d">Period end <input type="date" id="period-to" value="${run?.to||'2026-10-18'}"></label>${button(icon('payroll')+' Calculate draft','calculate','','primary')}<span class="spacer"></span><select id="payroll-run" aria-label="Select saved payroll"><option value="">Current draft</option>${store.data.runs.map(r=>`<option value="${r.id}" ${r.id===selectedRun?'selected':''}>${r.from} → ${r.to} · ${r.status}</option>`).join('')}</select></div>${run?renderRun(run):empty('Your next payroll starts here','Choose a date range and calculate a draft. Review every line before approval.')}</section>${run?.held?.length?`<section class="card"><div class="card-head"><div><h2>Held records</h2><p class="subtext">These sessions are excluded from this payroll snapshot.</p></div><span class="mini-badge">${run.held.length} records</span></div><div class="table-scroll"><table>${th(['Teacher','Session','Why it is held',''])}<tbody>${run.held.map(h=>`<tr><td>${person(h.teacher)}</td><td>${e(h.session.slice(0,12))}</td><td>${e(h.reason)}</td><td>${button('Review','session-detail',h.session,'small')}</td></tr>`).join('')}</tbody></table></div></section>`:''}`;}
  function renderRun(run){const totals=store.total(run),ids=[...new Set(run.lines.map(l=>l.teacher))];return `<div class="card-head"><div><h2>${run.status==='Draft'?'Payroll preview':'Approved payroll snapshot'}</h2><p class="subtext">${run.from} → ${run.to} · ${run.lines.length} eligible sessions</p></div><div class="flex gap-2 items-center">${badge(run.status)}${run.status==='Draft'?button('Approve payroll '+icon('arrow'),'approve-payroll','','primary small'):run.status==='Approved'?button('Void unpaid run','void',run.id,'small'):''}</div></div><div class="table-scroll"><table>${th(['Teacher','Minutes / hours','Gross (MMK)','Adjustment','Net (MMK)',''])}<tbody>${ids.map(id=>{const t=store.total(run,id);return `<tr><td>${person(id)}</td><td>${t.minutes} <small style="color:#9eaa8b">/ ${(t.minutes/60).toFixed(2)} hr</small></td><td>${mmk(t.gross)}</td><td>${mmk(t.adjustments)} ${run.status==='Draft'?button('Edit','adjustment',id,'small'):''}</td><td><strong>${mmk(t.net)}</strong></td><td>${button('Breakdown','breakdown',id,'small')}</td></tr>`;}).join('')}</tbody></table></div><div class="payroll-totals"><div><span>Verified teaching</span><strong>${(totals.minutes/60).toFixed(2)} <small style="font-size:12px">hours</small></strong></div><div><span>Teachers included</span><strong>${ids.length}</strong></div><div style="text-align:right"><span>Total payable · MMK</span><strong>${mmk(totals.net)}</strong></div></div>`;}
  function payments(){const runs=store.data.runs.filter(r=>r.status==='Approved'),rows=runs.flatMap(r=>[...new Set(r.lines.map(l=>l.teacher))].filter(id=>role==='admin'||id===teacherId).map(id=>({run:r,id,payment:store.data.payments.find(p=>p.run===r.id&&p.teacher===id&&p.status==='Paid')})));return head(role==='admin'?'PAYMENT RECORDS':'MY PAYMENT SUMMARY',role==='admin'?'Every payment, accounted for.':'Your teaching, recognised.',role==='admin'?'ငွေပေးချေပြီးမှ Paid အဖြစ်မှတ်ပါ။ တကယ့် bank transfer မလုပ်ပါ။':'Admin အတည်ပြုပြီး ဆရာကြေးနဲ့ ပေးချေမှုအခြေအနေကို ကြည့်ပါ။')+`<section class="stats-grid">${stat('Approved payroll',runs.length,'periods','Frozen payroll snapshots','payroll')}${stat('Total approved',mmk(rows.reduce((n,x)=>n+store.total(x.run,x.id).net,0)),'MMK','Approved amounts','payments')}${stat('Paid',mmk(rows.filter(x=>x.payment).reduce((n,x)=>n+x.payment.amount,0)),'MMK','Manually recorded','check')}${stat('Awaiting payment',rows.filter(x=>!x.payment).length,'teachers','Approved, not yet paid','clock',true)}</section><section class="card"><div class="card-head"><h2>${role==='admin'?'Teacher payments':'My approved payments'}</h2><span class="mini-badge">Manual payment history</span></div><div class="table-scroll"><table>${th(['Teacher','Payroll period','Net (MMK)','Payment status',''])}<tbody>${rows.map(x=>`<tr><td>${person(x.id)}</td><td>${day(x.run.from+'T00:00:00+06:30')} – ${day(x.run.to+'T00:00:00+06:30')}</td><td><strong>${mmk(store.total(x.run,x.id).net)}</strong></td><td>${badge(x.payment?'Paid':'Not paid')}${x.payment?`<div class="subtext" style="font-size:9px">${e(x.payment.method)} · ${e(x.payment.date)}</div>`:''}</td><td><div class="row-actions">${role==='admin'&&!x.payment?`<button class="btn primary small" data-action="pay" data-id="${x.run.id}" data-teacher="${x.id}">Record payment</button>`:`<button class="btn small" data-action="payment-detail" data-id="${x.run.id}" data-teacher="${x.id}">View details</button>`}${role==='admin'&&x.payment?button('Reverse','reverse',x.payment.id,'small'):''}</div></td></tr>`).join('')}</tbody></table></div>${rows.length?'':empty('No approved payments yet',role==='admin'?'Calculate and approve a payroll to see teacher payments here.':'Your approved payroll will appear here after Admin review.')}</section>${store.data.payments.some(p=>p.status==='Reversed')?`<div class="notice" style="margin-top:20px">${icon('audit')} ${store.data.payments.filter(p=>p.status==='Reversed'&&(role==='admin'||p.teacher===teacherId)).length} reversed payment record(s) retained in activity history.</div>`:''}`;}
  function audit(){return head('WORKSPACE ACTIVITY','A clear trail, every step.','မှတ်တမ်းပြောင်းလဲမှု၊ စစ်ဆေးမှုနဲ့ ငွေပေးချေမှု history။')+`<section class="card"><div class="card-head"><h2>Activity log</h2><span class="mini-badge">${store.data.audit.length} events</span></div>${store.data.audit.map(a=>`<div class="activity-item"><span class="activity-dot"></span><div><strong>${e(a.action)}</strong><p>${e(a.detail)}<br>${e(a.actor)}</p></div><time>${day(a.at)} · ${time(a.at)}</time></div>`).join('')}</section>`;}
  function render(){const allowed=role==='admin'?['overview','teachers','classes','sessions','reviews','payroll','payments','audit']:['home','sessions','reviews','payments'];if(!allowed.includes(page))page=role==='admin'?'overview':'home';nav();const views={overview,home,sessions,reviews,teachers,classes,payroll,payments,audit};window.destroyControls('#main');$('#main').html(views[page]());window.enhanceControls('#main');if(page==='sessions')filterSessions();}
  function sessionDetail(id){const s=store.session(id),t=teacher(s.teacher);if(role==='teacher'&&s.teacher!==teacherId)return toast('This record belongs to another teacher.');const reason=store.reason(s),requests=store.data.corrections.filter(c=>c.session===id);openModal('Class record details',`<div class="flex items-center justify-between">${person(s.teacher)}${badge(s.status)}</div><div class="info-grid"><div><small>Class / date</small><strong>${e(cls(s.classId).subject)} · ${day(s.start)}</strong></div><div><small>Effective teaching time</small><strong>${time(s.start)} – ${time(s.end)}</strong></div><div><small>Original time</small><strong>${time(s.originalStart)} – ${time(s.originalEnd)}</strong></div><div><small>Duration / hourly rate</small><strong>${s.end?EduDemo.mins(s.start,s.end)+' min':'Missing checkout'} / ${mmk(store.rate(s)||0)} MMK</strong></div></div><div class="detail-row"><span>Record source</span><strong>${e(s.source)}</strong></div><div class="detail-row"><span>Payroll eligibility</span><strong>${e(reason||'Eligible for payroll')}</strong></div>${s.note?`<p class="request-reason">${e(s.note)}</p>`:''}${s.reviewNote?`<p class="request-reason">Admin: ${e(s.reviewNote)}</p>`:''}${requests.length?`<hr class="divider"><div class="eyebrow">CORRECTION HISTORY</div>${requests.map(c=>`<div class="detail-row"><span>${time(c.start)} – ${time(c.end)}<br>${e(c.reason)}</span><strong>${badge(c.status)}</strong></div>`).join('')}`:''}<div class="form-actions">${!store.locked(s)&&!store.pending(s)?button('Request correction','request',id):''}${role==='admin'&&!store.locked(s)&&s.end&&!store.pending(s)?button('Review & verify','verify',id,'primary'):''}${button('Close','close-modal')}</div>`,s.id);}
  const handlers={
    'logout':()=>{sessionStorage.removeItem('ai14-demo-session');location.replace('login.html');},
    'close-modal':closeModal,
    'help':()=>openModal('Make yourself at home.',`<p class="request-reason">ဤ prototype က UI demo သာဖြစ်ပါတယ်။ Backend၊ database၊ real login နဲ့ bank transfer မရှိပါ။ Demo changes ကို browser localStorage ထဲမှာသာသိမ်းပါတယ်။</p><ol class="help-list"><li><strong>Explore as Admin.</strong> Open Verification to approve corrections, then verify the associated class record.</li><li><strong>Try Teacher view.</strong> Sign out and use the Teacher demo account to check in/out or request a time correction.</li><li><strong>Build a payroll.</strong> Choose 12–18 October 2026, calculate, inspect a breakdown and approve.</li><li><strong>Record a payment.</strong> Open Payment history and add a fictional reference. No money is transferred.</li><li><strong>Start again.</strong> Reset demo data restores the sample workspace.</li></ol><p class="admin-note">Browser clock is used for live demo sessions. Production would require server timestamps and authentication.</p><div class="form-actions">${button('Start exploring','close-modal','','primary')}</div>`,'PROTOTYPE GUIDE'),
    'reset':()=>openModal('Reset the workspace?',`<p class="request-reason">This removes your prototype changes from this browser and restores the fictional sample data.</p><div class="form-actions">${button('Cancel','close-modal')}${button('Reset demo data','confirm-reset','','danger')}</div>`),
    'confirm-reset':()=>{store=new EduDemo.Store();draft=null;selectedRun=null;commit(()=>{},'Demo workspace restored.');},
    'session-detail':sessionDetail,
    'review-tab':id=>{reviewTab=id;render();},
    'checkin':id=>commit(()=>store.checkIn(teacherId,id),'Checked in. Have a wonderful class.'),
    'checkout':id=>commit(()=>{if(store.session(id).teacher!==teacherId)throw Error('Not your session.');store.checkOut(id);},'Checked out. Your record is ready for Admin review.'),
    'request':id=>{const s=store.session(id);if(role==='teacher'&&s.teacher!==teacherId)return;openModal('Request a time correction',`<p class="request-reason">${e(cls(s.classId).subject)} · ${day(s.start)}<br>Original record stays in your history.</p><form id="correction-form" data-id="${id}"><div class="form-grid">${field('Correct start time','start','datetime-local',localInput(s.start))}${field('Correct end time','end','datetime-local',localInput(s.end))}</div>${textarea('Why should this time change?','reason')}${formEnd('Submit request')}</form>`);},
    'withdraw':id=>commit(()=>store.withdraw(id),'Correction withdrawn.'),
    'review':id=>{const c=store.data.corrections.find(x=>x.id===id),s=store.session(c.session);openModal('Review time correction',`<p class="request-reason"><strong>${e(teacher(s.teacher).name)}</strong> · ${e(cls(s.classId).subject)}<br>${e(c.reason)}</p><div class="time-compare"><div class="time-box"><label>ORIGINAL</label><strong>${time(s.originalStart)} – ${time(s.originalEnd)}</strong></div>${icon('arrow')}<div class="time-box new"><label>REQUESTED</label><strong>${time(c.start)} – ${time(c.end)}</strong></div></div><form id="review-form" data-id="${id}">${selectField('Decision','decision','<option>Approved</option><option>Rejected</option>')}<label class="field"><span>Admin comment · required when rejecting</span><textarea name="comment" placeholder="မှတ်ချက် ရေးပါ…"></textarea></label><p class="admin-note">After approval, verify the class record separately.</p>${formEnd('Save review')}</form>`);},
    'verify':id=>{const s=store.session(id);openModal('Verify class record',`<p class="request-reason">${e(teacher(s.teacher).name)} · ${e(cls(s.classId).subject)}<br>${day(s.start)} · ${time(s.start)} – ${time(s.end)}</p>${s.flag?`<div class="notice">${e(s.flag)}</div>`:''}<form id="verify-form" data-id="${id}">${selectField('Review decision','decision','<option>Verified</option><option>Rejected</option>')}<label class="field"><span>Reason · required for rejection or exception resolution</span><textarea name="reason"></textarea></label>${formEnd('Save verification')}</form>`);},
    'add-session':()=>openModal('Add a completed class',`<form id="session-form"><div class="form-grid">${selectField('Teacher','teacher',opts(store.data.teachers.filter(t=>t.active),'T001'))}${selectField('Class','classId',opts(store.data.classes.filter(c=>c.active),'C101'))}${field('Start · Yangon time','start','datetime-local','2026-10-19T09:00')}${field('End · Yangon time','end','datetime-local','2026-10-19T10:00')}</div>${textarea('Reason for entering on behalf of the teacher','reason')}<p class="admin-note">Saved as Pending verification. Teacher can see this entry.</p>${formEnd('Save class record')}</form>`),
    'add-teacher':()=>openModal('Welcome a teacher',`<form id="teacher-form">${field('Full name','name')}${field('Email · demo profile only','email','email')}<div class="form-grid">${field('Hourly rate · MMK','rate','number','10000')}${field('Effective from','from','date','2026-10-01')}</div><p class="admin-note">This creates a demo profile only. It does not send an invitation or create a real account.</p>${formEnd('Add teacher')}</form>`),
    'toggle-teacher':id=>commit(()=>{const t=teacher(id);t.active=!t.active;store.log('Teacher '+(t.active?'activated':'deactivated'),t.name);},'Teacher status updated.'),
    'toggle-class':id=>commit(()=>{const c=cls(id);c.active=!c.active;store.log('Class status updated',c.name);},'Class status updated.'),
    'teacher-profile':id=>{const t=teacher(id);openModal('Teacher profile & rates',`${person(id)}<p class="request-reason" style="margin-top:15px">${e(t.email)}<br>${t.assignments.map(x=>e(cls(x).subject)).join(' · ')||'No classes assigned'}</p><div class="eyebrow">HOURLY RATE HISTORY</div>${[...t.rates].sort((a,b)=>b.from.localeCompare(a.from)).map(r=>`<div class="detail-row"><span>Effective ${r.from}</span><strong>${mmk(r.rate)} MMK/hour</strong></div>`).join('')}<hr class="divider"><form id="rate-form" data-id="${id}"><div class="form-grid">${field('New hourly rate · MMK','rate','number')}${field('Effective from','from','date',localDate())}</div>${textarea('Rate change reason','reason')}${formEnd('Add rate version')}</form>`);},
    'add-class':()=>openModal('Add a class',`<form id="class-form">${field('Class name','name')}${field('Subject','subject')}${formEnd('Add class')}</form>`),
    'assignments':id=>openModal('Assign teachers',`<p class="request-reason">${e(cls(id).name)} · ${id}</p><form id="assignment-form" data-id="${id}">${store.data.teachers.map(t=>`<label class="flex items-center gap-3" style="margin:15px 0;font-size:12px;color:#6d855c"><input type="checkbox" name="teachers" value="${t.id}" ${t.assignments.includes(id)?'checked':''}>${e(t.name)}</label>`).join('')}${textarea('Assignment or coverage reason','reason')}${formEnd('Save assignments')}</form>`),
    'calculate':()=>{try{draft=store.draft($('#period-from').val(),$('#period-to').val());selectedRun=null;render();toast('Draft calculated. Review the details before approval.');}catch(err){fail(err);}},
    'adjustment':id=>openModal('Payroll adjustment',`<p class="request-reason">${e(teacher(id).name)} · ${draft.from} → ${draft.to}</p><form id="adjustment-form" data-id="${id}">${field('Adjustment · MMK · negative to deduct','amount','number',draft.adjustments[id]?.amount||0)}${textarea('Adjustment reason','reason')}${formEnd('Save adjustment')}</form>`),
    'approve-payroll':()=>{if(!draft?.lines.length)return toast('No eligible sessions to approve.');openModal('Approve this payroll?',`<div class="balance-panel"><div class="eyebrow">TOTAL PAYABLE · MMK</div><h2>${mmk(store.total(draft).net)}</h2><p>${draft.lines.length} verified sessions · ${draft.held.length} held records<br>${draft.from} → ${draft.to}</p></div><p class="request-reason" style="margin-top:20px">အတည်ပြုပြီးတဲ့ amount နဲ့ session details တွေကို snapshot အဖြစ်သိမ်းပါမယ်။ This does not mark teachers as paid.</p><div class="form-actions">${button('Review again','close-modal')}${button('Approve payroll','confirm-approve','','primary')}</div>`);},
    'confirm-approve':()=>commit(()=>{const r=store.approve(draft);selectedRun=r.id;draft=null;},'Payroll approved. A clear snapshot is saved.'),
    'void':id=>openModal('Void unpaid payroll',`<form id="void-form" data-id="${id}"><p class="request-reason">Only payroll with no active paid teachers can be voided. History will be retained.</p>${textarea('Why is this payroll being voided?','reason')}${formEnd('Void payroll')}</form>`),
    'breakdown':id=>{const r=selectedRun?store.data.runs.find(x=>x.id===selectedRun):draft;showBreakdown(r,id);},
    'pay':(id,el)=>{const t=$(el).data('teacher'),r=store.data.runs.find(x=>x.id===id);openModal('Record a teacher payment',`<div class="balance-panel"><div class="eyebrow">${e(teacher(t).name)} · MMK</div><h2>${mmk(store.total(r,t).net)}</h2><p>${r.from} → ${r.to}</p></div><form id="payment-form" data-id="${id}" data-teacher="${t}" style="margin-top:20px"><div class="form-grid">${selectField('Payment method','method','<option>Bank transfer</option><option>Cash</option><option>Mobile wallet</option>')}${field('Actual payment date','date','date',localDate())}</div>${field('Reference or cash receipt note','reference')}<p class="admin-note">Manual demo record only. No bank connection or transfer.</p>${formEnd('Mark as paid')}</form>`);},
    'payment-detail':(id,el)=>showBreakdown(store.data.runs.find(x=>x.id===id),$(el).data('teacher')),
    'reverse':id=>openModal('Reverse a payment record',`<form id="reverse-form" data-id="${id}"><p class="request-reason">This corrects the demo record only. It does not return money. Original history stays visible.</p>${textarea('Reversal reason','reason')}${formEnd('Reverse record')}</form>`)
  };
  function showBreakdown(run,id){if(role==='teacher'&&id!==teacherId)return;const totals=store.total(run,id),pay=store.data.payments.find(p=>p.run===run.id&&p.teacher===id&&p.status==='Paid');openModal('Teacher payroll breakdown',`${person(id)}<p class="request-reason" style="margin-top:15px">${run.from} → ${run.to} · ${run.status}</p>${run.lines.filter(l=>l.teacher===id).map(l=>`<div class="detail-row"><span>${day(l.start)} · ${e(cls(l.classId).subject)}<br>${l.minutes} min × ${mmk(l.rate)} MMK/hr</span><strong>${mmk(l.amount)} MMK</strong></div>`).join('')}<div class="detail-row"><span>Adjustment${run.adjustments?.[id]?.reason?'<br>'+e(run.adjustments[id].reason):''}</span><strong>${mmk(totals.adjustments)} MMK</strong></div><div class="detail-row"><span>Net payable</span><strong>${mmk(totals.net)} MMK</strong></div>${pay?`<div class="notice green" style="margin-top:17px">Paid · ${e(pay.method)} · ${e(pay.date)}<br>Reference: ${e(pay.reference)}</div>`:''}<div class="form-actions">${button('Close','close-modal','','primary')}</div>`);}
  const adminActions=new Set(['review','verify','add-session','add-teacher','toggle-teacher','toggle-class','teacher-profile','add-class','assignments','calculate','adjustment','approve-payroll','confirm-approve','void','pay','reverse']);
  $(document).on('click','[data-action]',function(){const action=$(this).data('action');if(role!=='admin'&&adminActions.has(action))return toast('Switch to Admin view for this action.');try{handlers[action]?.(String($(this).data('id')||''),this);}catch(err){fail(err);}});
  $(document).on('submit','#modal form',function(ev){ev.preventDefault();const f=this,id=$(f).data('id'),data=Object.fromEntries(new FormData(f));if(role!=='admin'&&!['correction-form'].includes(f.id))return toast('Admin view required.');commit(()=>{
    switch(f.id){
      case 'correction-form':if(role==='teacher'&&store.session(id).teacher!==teacherId)throw Error('Not your session.');store.request(id,iso(data.start),iso(data.end),data.reason);break;
      case 'review-form':store.review(id,data.decision,data.comment);break;
      case 'verify-form':store.verify(id,data.decision,data.reason);break;
      case 'session-form':store.addSession(data.teacher,data.classId,iso(data.start),iso(data.end),data.reason);break;
      case 'teacher-form':{const rate=Number(data.rate);if(!Number.isSafeInteger(rate)||rate<=0)throw Error('Enter a positive whole-MMK rate.');if(!data.name.trim())throw Error('Teacher name is required.');const tid='T'+String(store.data.teachers.length+1).padStart(3,'0');store.data.teachers.push({id:tid,name:data.name.trim(),email:data.email,rates:[{from:data.from,rate}],assignments:[],active:true,tone:store.data.teachers.length});store.log('Teacher added',data.name);break;}
      case 'rate-form':{const t=teacher(id),rate=Number(data.rate);if(!Number.isSafeInteger(rate)||rate<=0)throw Error('Enter a positive whole-MMK rate.');if(t.rates.some(r=>r.from===data.from))throw Error('A rate already starts on this date. Choose another date.');t.rates.push({from:data.from,rate});store.log('Rate version added',t.name+' · '+mmk(rate)+' MMK/hr · '+data.reason);break;}
      case 'class-form':{const cid='C'+String(store.data.classes.length+101);store.data.classes.push({id:cid,name:data.name.trim(),subject:data.subject.trim(),active:true});store.log('Class added',data.name);break;}
      case 'assignment-form':{const checked=new FormData(f).getAll('teachers');store.data.teachers.forEach(t=>{t.assignments=t.assignments.filter(c=>c!==id);if(checked.includes(t.id))t.assignments.push(id);});store.log('Assignments updated',cls(id).name+' · '+data.reason);break;}
      case 'adjustment-form':{const amount=Number(data.amount);if(!Number.isSafeInteger(amount))throw Error('Enter a whole-MMK amount.');draft.adjustments[id]={amount,reason:data.reason};if(store.total(draft,id).net<0){delete draft.adjustments[id];throw Error('Net pay cannot be negative.');}break;}
      case 'payment-form':store.pay(id,$(f).data('teacher'),data.method,data.date,data.reference);break;
      case 'void-form':store.voidRun(id,data.reason);break;
      case 'reverse-form':store.reversePayment(id,data.reason);break;
    }
  },'Saved. Your workspace is up to date.');});
  $(document).on('input','#session-search',function(){query=this.value;filterSessions();});
  $(document).on('change','#session-filter',function(){sessionFilter=this.value;filterSessions();});
  $(document).on('change','#payroll-run',function(){selectedRun=this.value||null;render();});
  $('#menu-toggle').on('click',()=>$('#sidebar').toggleClass('open'));
  $(window).on('hashchange',()=>{page=location.hash.slice(1)||'overview';$('#sidebar').removeClass('open');render();window.scrollTo(0,0);});
  $('#modal').on('click',function(ev){if(ev.target===this)closeModal();});
  $(document).on('keydown',function(ev){if($('#modal').hasClass('hidden'))return;if(ev.key==='Escape')closeModal();if(ev.key==='Tab'){const list=$('#modal').find('button,input,select,textarea,a,[tabindex]:not([tabindex="-1"])').filter(':visible:not(:disabled)');const first=list[0],last=list[list.length-1];if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus();}}});
  setInterval(()=>$('#live-clock').text(time(new Date())),1000);
  page=location.hash.slice(1)||'overview';render();
});
